package app.kinnect.audit;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.io.*;import java.lang.reflect.*;

public final class CameraLiveSetupAudit extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 volatile Activity resumed;public void callActivityOnResume(Activity a){super.callActivityOnResume(a);resumed=a;}
 Activity open(String type,Intent intent)throws Exception{resumed=null;new Handler(Looper.getMainLooper()).post(()->getTargetContext().startActivity(intent));for(int n=0;n<100;n++){if(resumed!=null&&resumed.getClass().getName().endsWith(type))return resumed;Thread.sleep(100);}throw new AssertionError("Activity did not resume: "+type);}
 int checks;void check(boolean v,String m){if(!v)throw new AssertionError(m);checks++;}
 Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}
 Object call(Object o,String n,Class[] types,Object...args)throws Exception{Method m=o.getClass().getDeclaredMethod(n,types);m.setAccessible(true);return m.invoke(o,args);}
 View find(View v,String label){if(v instanceof TextView&&label.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View f=find(((ViewGroup)v).getChildAt(i),label);if(f!=null)return f;}return null;}
 void click(View v){if(v==null)throw new AssertionError("Missing view");View target=v;while(!target.isClickable()&&target.getParent() instanceof View)target=(View)target.getParent();final View item=target;runOnMainSync(()->item.performClick());}
 void shot(Activity a,String name)throws Exception{Thread.sleep(1100);try(FileOutputStream f=new FileOutputStream(new File(a.getExternalFilesDir(null),name))){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,f);}}
 public void onStart(){Bundle out=new Bundle();Activity camera=null,live=null;try{
  ClassLoader cl=getTargetContext().getClassLoader();Class<?> apiType=cl.loadClass("app.kinnect.live.NativeApi");call(apiType.getField("shared").get(null),"configure",new Class[]{String.class},"https://127.0.0.1:9");Class<?> i18n=cl.loadClass("app.kinnect.live.I18n");Method select=i18n.getDeclaredMethod("select",Context.class,String.class);select.setAccessible(true);select.invoke(null,getTargetContext(),"vi");
  camera=open("StudioActivity",new Intent().setClassName("app.kinnect.live","app.kinnect.live.StudioActivity").putExtra("mode","photo").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final Activity a=camera;Thread.sleep(1200);Object device=get(a,"device");check(device!=null,"Camera not opened");TextureView preview=(TextureView)get(a,"camera");check(preview.isAvailable(),"No camera texture");
  click(find(a.getWindow().getDecorView(),"LIVE"));Thread.sleep(200);check("live".equals(get(a,"mode")),"Mode not Live");check(get(a,"device")==device,"Camera restarted on Live tab");check(get(a,"camera")==preview,"Camera surface replaced");check(!a.isFinishing(),"Camera navigated away");Object setup=get(a,"liveSetup");Dialog sheet=(Dialog)get(setup,"dialog");check(sheet.isShowing(),"Missing setup sheet");check(((View)get(setup,"gameOptions")).getVisibility()==View.GONE,"Game field visible in chat");check(((View)get(a,"galleryAction")).getVisibility()!=View.VISIBLE,"Gallery duplicated in Live");shot(a,"live30-chat.png");
  click(find(sheet.getWindow().getDecorView(),"Chơi game"));check(((View)get(setup,"gameOptions")).getVisibility()==View.VISIBLE,"Game options not revealed");View start=find(sheet.getWindow().getDecorView(),"Bắt đầu");click(start);check(sheet.isShowing(),"Empty game dismissed setup");check(get(a,"device")==device,"Choosing game closed camera");Thread.sleep(4500);
  click(find(sheet.getWindow().getDecorView(),"Chọn game"));Object picker=get(setup,"picker");Dialog list=(Dialog)get(picker,"dialog");LinearLayout rows=(LinearLayout)get(picker,"results");check(rows.getChildCount()==12,"Game catalog count");click(rows.getChildAt(11));check("Minecraft".equals(get(setup,"game")),"Game not stored");check("Minecraft".contentEquals(((TextView)get(setup,"gameButton")).getText()),"Game label not updated");shot(a,"live30-game.png");
  View gameButton=(View)get(setup,"gameButton");check(gameButton.getWidth()>0&&gameButton.getHeight()>=48*a.getResources().getDisplayMetrics().density,"Game row small/clipped");click(find(sheet.getWindow().getDecorView(),"Trò chuyện"));check(((View)get(setup,"gameOptions")).getVisibility()==View.GONE,"Game options remain in chat");click(find(sheet.getWindow().getDecorView(),"Chơi game"));check("Minecraft".equals(get(setup,"game")),"Switch lost selection");
  Class<?> resolver=cl.loadClass("app.kinnect.live.LiveGameLaunch");Method resolve=resolver.getDeclaredMethod("intent",Context.class,String.class);resolve.setAccessible(true);Intent launch=(Intent)resolve.invoke(null,a,"Minecraft");check(launch!=null&&"app.kinnect.audit".equals(launch.getComponent().getPackageName()),"Game resolver wrong component");check(resolve.invoke(null,a,"")==null,"Empty game matched");check(resolve.invoke(null,a,"No such installed game xyz")==null,"Missing game matched");
  runOnMainSync(()->{try{call(get(a,"liveSetup"),"close",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});check(get(a,"device")==device,"Cancel closed camera");check(!a.isFinishing(),"Cancel left camera");click(find(a.getWindow().getDecorView(),"VIDEO"));check("video".equals(get(a,"mode")),"Video tab regression");check(((View)get(a,"galleryAction")).getVisibility()==View.VISIBLE,"Gallery missing in video");
  runOnMainSync(()->a.finish());Thread.sleep(150);live=open("LiveActivity",new Intent().setClassName("app.kinnect.live","app.kinnect.live.LiveActivity").putExtra("host",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final Activity l=live;
  runOnMainSync(()->{try{set(l,"gameTitle","Minecraft");set(l,"gameSession",true);call(l,"openGameApp",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(700);android.view.accessibility.AccessibilityNodeInfo window=getUiAutomation().getRootInActiveWindow();check(window!=null&&"app.kinnect.audit".contentEquals(window.getPackageName()),"Selected game did not launch");check(get(l,"socket")==null,"Offline audit must not create public room");getUiAutomation().executeShellCommand("input keyevent 4").close();Thread.sleep(200);runOnMainSync(()->{try{set(l,"gameSession",false);}catch(Exception e){throw new RuntimeException(e);}});
  runOnMainSync(()->{try{set(l,"cameraSetup",true);set(l,"ready",true);set(l,"gameComments",false);call(l,"requestGameProjection",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(500);check((Boolean)get(l,"projectionPrompt"),"OS consent not requested");check(!(Boolean)get(l,"gameSession"),"Capturing before consent");getUiAutomation().executeShellCommand("input keyevent 4").close();Thread.sleep(600);check(l.isFinishing(),"Cancel should return to camera");check(!(Boolean)get(l,"gameSession"),"Cancel started capture");
  out.putString("result","PASS "+checks+": shared camera identity, bottom setup, conditional game row, missing-game guard, picker12, selection persistence, cancel, video gallery regression, exact installed-game launch. No public broadcast.");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("error",e.toString());finish(Activity.RESULT_CANCELED,out);}finally{final Activity c=camera,l=live;runOnMainSync(()->{if(c!=null&&!c.isFinishing())c.finish();if(l!=null&&!l.isFinishing())l.finish();});}
 }
}
